with parsed as (select id, customer_id, created_at, items, ship_to, attributes, coalesce(attributes['device'], 'none') as device_or_default, array_contains(map_keys(attributes), 'weight_kg') as has_weight_kg, transform(items, x -> x.product_id) as product_ids, array_join(array_sort(coupon_codes), ',') as coupons_text from carts) select customer_id, min(created_at) as started_at, count(*) as event_count from parsed group by customer_id;
